-- The places of the app, for the server to check the captures. Written by
-- `uv run python -m lutece_pipeline.export_places` from the bundle
-- 27d98099e502: do not edit by hand.
on conflict (id) do update set
  title = excluded.title,
  location = excluded.location,
  footprint = excluded.footprint,
  reach_m = excluded.reach_m,
  arrondissement = excluded.arrondissement,
  rarity_tier = excluded.rarity_tier,
  bundle_version = excluded.bundle_version;
